head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > checkcomboboxRangeSeparator]<br/>inputType='checkcombobox' 인 Column 에서 연속적으로 선택된 아이템을 'x-y' 형태로 축약해 표시할 구분자를 설정합니다.",
    "validation" : [
        "구분자 설정 시, 'x-y' 범위 형태로 선택 아이템을 축약해 표시할때 적용할 구분자를 텍스트로 설정합니다.",
        "속성값을 설정하지 않으면 선택된 아이템의 라벨값이 Column 에 모두 표시됩니다.",
        "checkcomboboxRangeSeparator 속성을 설정하면 선택 아이템을 축약하여 표시하는 기능이 활성화 됩니다.",
        "Column 이 편집 모드로 진입한 이후부터 축약 형태로 표시되며, 그 전에는 선택된 아이템의 라벨값이 모두 표시됩니다.",
        "checkcomboboxRangeSeparator 속성 설정 시, 아이템 리스트창에 표시된 아이템 순서를 기준으로 아이템을 연속으로 선택하면 '시작 아이템 라벨 + checkcomboboxRangeSeparator 속성값 + 마지막 아이템 라벨' 로 축약되어 표시됩니다.",
        "checkcomboboxRangeSeparator 속성 설정 시, 연속으로 선택되지 않은 아이템은 축약되지 않고 각각의 라벨로 표시됩니다.",
        "checkcomboboxRangeSeparator 속성 설정 시, 마지막 아이템과 바로 이전 아이템 둘만 연속으로 선택된 경우 각각의 라벨로 표시됩니다.",
        "checkcomboboxRangeSeparator 속성 설정 시, 축약된 라벨과 각각 표시되는 라벨은 Column 의 separator 속성값이 구분자로 적용됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  - 검증 대상은 의미 있는 값(~), 전제 조건 separator 는 미설정
    con_checkcomboboxRangeSeparator.setValue("~");
    con_separator.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 1월 ~ 12월 (value 1 ~ 12), 행별 선택 패턴
scwin.itemCount = 12;
scwin.rowPattern = [
    { "name" : "연속 3개 이상 + 단독", "month" : [1, 3, 4, 5, 6, 10] },
    { "name" : "중간 연속 2개 + 단독", "month" : [2, 3, 7] },
    { "name" : "마지막 아이템 포함 연속 2개", "month" : [5, 11, 12] },
    { "name" : "마지막 아이템 포함 연속 3개", "month" : [1, 10, 11, 12] },
    { "name" : "연속 없음", "month" : [2, 4, 6] }
];



// comp 생성
//  - name  : 선택 패턴 설명 Column
//  - month : 검증 대상 Body Column (inputType=checkcombobox, 아이템 1월 ~ 12월)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cRangeSeparator = con_checkcomboboxRangeSeparator.getValue();
    let cSeparator = con_separator.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] month Column (inputType=checkcombobox, 아이템 1월 ~ 12월) 의 선택값을 행마다 다르게 설정\n[절차] Target 재생성 -> month 셀 더블클릭으로 편집 진입 -> 아이템 체크 변경 또는 그대로 -> 셀 밖 클릭으로 편집 종료\n[확인] 재생성 직후 / 편집 종료 후 셀 표시값 비교, 편집하지 않은 행은 셀 표시값 확인 버튼으로 확인"', '', 'label1');

    // dataList 생성 (선택값은 Column 의 separator 로 연결, 미설정 시 기본 구분자 공백)
    let dataSeparator = (cSeparator === '') ? ' ' : cSeparator;
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="month" name="month" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowPattern.map(function (row) {
        return { "name" : row.name, "month" : row.month.join(dataSeparator) };
    }), false);

    // month Column 속성
    let attrMonth = ' inputType="checkcombobox"';
    attrMonth += (cSeparator === '') ? '' : ' separator="' + cSeparator + '"';
    attrMonth += (cRangeSeparator === '') ? '' : ' checkcomboboxRangeSeparator="' + cRangeSeparator + '"';

    // 정적 아이템 1월 ~ 12월
    let strItems = '<w2:choices>';
    for (let i = 1; i <= scwin.itemCount; i++) {
        strItems += '<w2:item><w2:label>' + i + '월</w2:label><w2:value>' + i + '</w2:value></w2:item>';
    }
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:260px;" ev:oneditend="scwin.target1_oneditend">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="선택 패턴"></w2:column>';
    strTarget += '<w2:column width="360" style="" inputType="text" id="column2" value="month (checkcombobox)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="360" style="text-align:left;" id="month" value=""' + attrMonth + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 2, 4 : 재생성 직후(편집 모드 진입 전) 행별 셀 표시값
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("재생성 직후 표시값 : " + scwin.getAllCellText());
    }, 100);
}



// month Column 셀의 표시 텍스트 (따옴표로 감싸 공백 구분자 확인)
scwin.getCellText = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_1']");
    return td ? "'" + td.textContent + "'" : "셀 없음";
}



scwin.getAllCellText = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arr.push(i + "행=" + scwin.getCellText(i));
    }
    return arr.join(" / ");
}



// validation 1, 3 ~ 8 : 편집 종료 후 해당 행 선택값과 셀 표시값
scwin.target1_oneditend = function (rowIndex, colIndex) {
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("편집 종료 후 " + rowIndex + "행 : 선택값 '" + dlt_bind.getCellData(rowIndex, "month") + "' -> 표시값 " + scwin.getCellText(rowIndex));
    }, 100);
}



// 편집 모드 진입 이후 전체 행 셀 표시값 비교
scwin.btn_checkCellText_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("셀 표시값 : " + scwin.getAllCellText());
}
